<?php
session_start(); require_once __DIR__.'/database.php';
$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH); $method=$_SERVER['REQUEST_METHOD']; $b=input();
try {
 if($path==='/api/health') { db(); json_response(['ok'=>true,'database'=>'mariadb']); }
 if($path==='/api/logout'){session_destroy();json_response(['ok'=>true]);}
 if($path==='/api/me'){ $u=session_user(); $u?json_response(['user'=>$u]):json_response(['error'=>'Unauthenticated'],401); }
 if($path==='/api/auth/login'&&$method==='POST'){ $role=$b['role']??''; $c=db(); if($role==='franchisee_login'){$st=$c->prepare('SELECT u.id,u.name,fr.franchise_number FROM users u JOIN franchisees f ON f.user_id=u.id JOIN franchises fr ON fr.franchisee_id=f.franchisee_id WHERE u.mobile_number=? AND fr.franchise_number=? AND u.account_status="active" LIMIT 1');$st->bind_param('ss',$b['mobileNumber'],$b['franchiseNumber']);}else{$st=$c->prepare('SELECT u.id,u.name FROM users u JOIN roles r ON r.role_id=u.role_id WHERE u.username=? AND u.password=? AND u.account_status="active" AND r.role_name=? LIMIT 1');$hp=hash_password($b['password']??'');$st->bind_param('sss',$b['username'],$hp,$role);} $st->execute();$row=$st->get_result()->fetch_assoc();if(!$row)json_response(['error'=>'Invalid username or password'],401);$u=['id'=>(int)$row['id'],'name'=>$row['name'],'role'=>$role==='franchisee_login'?'franchisee':$role,'franchiseNumber'=>$row['franchise_number']??null];$_SESSION['tritrack_user']=$u;json_response(['user'=>$u]); }
 if($path==='/api/auth/signup/request-otp'&&$method==='POST'){if(!$b['fullName']||!$b['franchiseNumber']||!$b['mobileNumber'])json_response(['error'=>'All registration fields are required'],400);$otp=(string)random_int(100000,999999);$_SESSION['pending_otp']=['fullName'=>$b['fullName'],'franchiseNumber'=>$b['franchiseNumber'],'mobileNumber'=>$b['mobileNumber'],'otp'=>$otp,'expires'=>time()+300];json_response(['verificationId'=>$b['mobileNumber'],'developmentOtp'=>$otp,'message'=>'Development OTP generated because SMS_PROVIDER is not configured']);}
 if($path==='/api/auth/signup/verify'&&$method==='POST'){ $p=$_SESSION['pending_otp']??null;if(!$p||$p['expires']<time()||$p['otp']!==($b['otp']??''))json_response(['error'=>'Invalid or expired OTP'],401);$c=db();$c->begin_transaction();$role=$c->query("SELECT role_id FROM roles WHERE role_name='franchisee'")->fetch_assoc();$pw=hash_password(bin2hex(random_bytes(12)));$st=$c->prepare('INSERT INTO users(role_id,name,mobile_number,password,account_status) VALUES(?,?,?,?,"active")');$st->bind_param('isss',$role['role_id'],$p['fullName'],$p['mobileNumber'],$pw);$st->execute();$uid=$c->insert_id;$first=$p['fullName'];$last='';$addr='To be completed';$st=$c->prepare('INSERT INTO franchisees(user_id,first_name,last_name,address,contact_number) VALUES(?,?,?,?,?)');$st->bind_param('issss',$uid,$first,$last,$addr,$p['mobileNumber']);$st->execute();$fid=$c->insert_id;$st=$c->prepare('INSERT INTO franchises(franchisee_id,franchise_number,franchise_status) VALUES(?,?,"active")');$st->bind_param('is',$fid,$p['franchiseNumber']);$st->execute();$c->commit();$u=['id'=>$uid,'name'=>$p['fullName'],'role'=>'franchisee','franchiseNumber'=>$p['franchiseNumber'],'mobileNumber'=>$p['mobileNumber']];$_SESSION['tritrack_user']=$u;unset($_SESSION['pending_otp']);json_response(['user'=>$u]);}
 if($path==='/api/dashboard'){if(!($u=session_user()))json_response(['error'=>'Unauthenticated'],401);$c=db();if($u['role']==='staff_admin'){$q=$c->query('SELECT fr.franchise_number AS franchise, CONCAT(f.first_name," ",f.last_name) AS owner, fr.franchise_status AS status FROM franchises fr JOIN franchisees f ON f.franchisee_id=fr.franchisee_id LIMIT 50');$rows=$q->fetch_all(MYSQLI_ASSOC);}else{$st=$c->prepare('SELECT fr.franchise_number,fr.franchise_status FROM franchises fr JOIN franchisees f ON f.franchisee_id=fr.franchisee_id WHERE f.user_id=?');$st->bind_param('i',$u['id']);$st->execute();$rows=$st->get_result()->fetch_all(MYSQLI_ASSOC);}json_response(['role'=>$u['role'],'user'=>$u,'records'=>$rows]);}
 json_response(['error'=>'Route not found'],404);
} catch(Throwable $e){json_response(['error'=>'Server/database error','detail'=>getenv('APP_DEBUG')==='true'?$e->getMessage():null],500);}
